        `,showInDialog:!1,options:[{value:"fresh",label:"Origin default branch (fresh)"},{value:"head",label:"Current checkout HEAD (head)"}]},sparsePaths:{type:"array",label:"Worktree Sparse Paths",category:"Advanced",requiresRestart:!0,default:[],description:VQ`
